        yield scrapy.Request(method="GET",
                             url="https://www.udacity.com/api/summaries?queries=" + quote_plus(json.dumps(queries)),
                             callback=self.parse_totals)

    def parse_totals(self, response):
        print(json.loads(response.body[5:].strip())["summaries"]["default"][0]["data"]["total_enrollments"])

def breadcrumb(self):
    breadcrumb = self.name
    def get_next_parent(obj=None):
        if obj is None:
            return None
        if obj.parent:
            return obj.parent
        return None
    obj = self
    while get_next_parent(obj=obj):
        obj = get_next_parent(obj=obj)
        breadcrumb = '%s > %s' % (obj.name, breadcrumb)
    return breadcrumb

