def cycling(p, start, done):
    while not done[e]:
        done[e] = True
        e = p[e]
        yield e

def toCycle(p):
    done = [False]*len(p)
    cycles = [tuple(cycling(p, 0, done))]
    while not all(done):
        start = done.index(False)
        cycles.append(tuple(cycling(p, start, done)))
    return cycles

#convert base 10 to any base between 2 and 16
def convBase(n, base):
    charSeq = '0123456789ABCDEF'
    if n < base:
        return charSeq[n]
    else:
        return convBase(n//base, base) + charSeq[n%base]

