class FixProgress:
    def __init__(self):
        self.saw_progress = False

    def write(self, s):
        if 'Progress:' in s:
            self.saw_progress = True
        if s == '\n' and self.saw_progress:
            sys.stdout.write('\r')
            self.saw_progress = False
        else:
            sys.stdout.write(s)

    def flush(self):
        sys.stdout.flush()

