class Generator:
    operations = {}

    def __init__(self, state):
        self._state = state

    @classmethod
    def init_operations(cls):
        cls.operations = {
            PLUS:  cls.plus,    
            MINUS:  cls.minus
        }

    def plus(self, a, b):
        # Depends on state
        return a + b

    def minus(self, a, b):
        return a - b if self._state else b - a


    def generate(self):
        a, b = 5, 10
        for op in self.operations:
            print( self.operations[op](self, a, b) )

