def non_Destructive_pixel_addition(original, segmentated):

    to_be_added = np.matrix(np.where(segmentated)).transpose()

    n, m = np.shape(to_be_added)

    for k in range(n):
        i = to_be_added[k, 0]
        j = to_be_added[k, 1]
        if (original[i,j] == 0):
            original[i,j] = segmentated[i,j]

